// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetHealthz Liveness probe
	// (GET /healthz)
	GetHealthz(ctx context.Context, request GetHealthzRequestObject) (GetHealthzResponseObject, error)
	// GetReadyz Readiness probe
	// (GET /readyz)
	GetReadyz(ctx context.Context, request GetReadyzRequestObject) (GetReadyzResponseObject, error)
	// CreateCategory Create a category
	// (POST /v1/admin/categories)
	CreateCategory(ctx context.Context, request CreateCategoryRequestObject) (CreateCategoryResponseObject, error)
	// UpdateCategory Edit a category
	// (PATCH /v1/admin/categories/{id})
	UpdateCategory(ctx context.Context, request UpdateCategoryRequestObject) (UpdateCategoryResponseObject, error)
	// CreateCategoryAttribute Add an attribute to a category
	// (POST /v1/admin/categories/{id}/attributes)
	CreateCategoryAttribute(ctx context.Context, request CreateCategoryAttributeRequestObject) (CreateCategoryAttributeResponseObject, error)
	// DeleteCategoryAttribute Delete an attribute
	// (DELETE /v1/admin/categories/{id}/attributes/{attributeId})
	DeleteCategoryAttribute(ctx context.Context, request DeleteCategoryAttributeRequestObject) (DeleteCategoryAttributeResponseObject, error)
	// UpdateCategoryAttribute Edit an attribute
	// (PATCH /v1/admin/categories/{id}/attributes/{attributeId})
	UpdateCategoryAttribute(ctx context.Context, request UpdateCategoryAttributeRequestObject) (UpdateCategoryAttributeResponseObject, error)
	// ListAdminSellers List seller profiles by verification status
	// (GET /v1/admin/sellers)
	ListAdminSellers(ctx context.Context, request ListAdminSellersRequestObject) (ListAdminSellersResponseObject, error)
	// VerifySeller Approve or reject a seller
	// (POST /v1/admin/sellers/{userId}/verification)
	VerifySeller(ctx context.Context, request VerifySellerRequestObject) (VerifySellerResponseObject, error)
	// ListCategories List the category tree
	// (GET /v1/categories)
	ListCategories(ctx context.Context, request ListCategoriesRequestObject) (ListCategoriesResponseObject, error)
	// GetCategory Get one category
	// (GET /v1/categories/{slug})
	GetCategory(ctx context.Context, request GetCategoryRequestObject) (GetCategoryResponseObject, error)
	// GetLocations List Ghana regions with district suggestions
	// (GET /v1/locations)
	GetLocations(ctx context.Context, request GetLocationsRequestObject) (GetLocationsResponseObject, error)
	// GetMe Get my account
	// (GET /v1/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// UpdateMe Update my account
	// (PATCH /v1/me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
	// GetMySellerProfile Get my seller profile
	// (GET /v1/me/seller-profile)
	GetMySellerProfile(ctx context.Context, request GetMySellerProfileRequestObject) (GetMySellerProfileResponseObject, error)
	// UpdateMySellerProfile Create or edit my seller profile
	// (PUT /v1/me/seller-profile)
	UpdateMySellerProfile(ctx context.Context, request UpdateMySellerProfileRequestObject) (UpdateMySellerProfileResponseObject, error)
	// CreateMediaUploadUrl Get a presigned upload URL
	// (POST /v1/media/upload-url)
	CreateMediaUploadUrl(ctx context.Context, request CreateMediaUploadUrlRequestObject) (CreateMediaUploadUrlResponseObject, error)
	// GetPublicSeller Get a seller's public profile
	// (GET /v1/sellers/{userId})
	GetPublicSeller(ctx context.Context, request GetPublicSellerRequestObject) (GetPublicSellerResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

